1	import slugify from 'slugify';
2	import prisma from '../../../prisma/prisma-client';
3	import HttpException from '../../models/http-exception.model';
4	import profileMapper from '../profile/profile.utils';
5	import articleMapper from './article.mapper';
6	import { Tag } from '../tag/tag.model';
7	
8	const buildFindAllQuery = (query: any, id: number | undefined) => {
9	  const queries: any = [];
10	  const orAuthorQuery = [];
11	  const andAuthorQuery = [];
12	
13	  orAuthorQuery.push({
14	    demo: {
15	      equals: true,
16	    },
17	  });
18	
19	  if (id) {
20	    orAuthorQuery.push({
21	      id: {
22	        equals: id,
23	      },
24	    });
25	  }
26	
27	  if ('author' in query) {
28	    andAuthorQuery.push({
29	      username: {
30	        equals: query.author,
31	      },
32	    });
33	  }
34	
35	  const authorQuery = {
36	    author: {
37	      OR: orAuthorQuery,
38	      AND: andAuthorQuery,
39	    },
40	  };
41	
42	  queries.push(authorQuery);
43	
44	  if ('tag' in query) {
45	    queries.push({
46	      tagList: {
47	        some: {
48	          name: query.tag,
49	        },
50	      },
51	    });
52	  }
53	
54	  if ('favorited' in query) {
55	    queries.push({
56	      favoritedBy: {
57	        some: {
58	          username: {
59	            equals: query.favorited,
60	          },
61	        },
62	      },
63	    });
64	  }
65	
66	  return queries;
67	};
68	
69	export const getArticles = async (query: any, id?: number) => {
70	  const andQueries = buildFindAllQuery(query, id);
71	  const articlesCount = await prisma.article.count({
72	    where: {
73	      AND: andQueries,
74	    },
75	  });
76	
77	  const articles = await prisma.article.findMany({
78	    where: { AND: andQueries },
79	    orderBy: {
80	      createdAt: 'desc',
81	    },
82	    skip: Number(query.offset) || 0,
83	    take: Number(query.limit) || 10,
84	    include: {
85	      tagList: {
86	        select: {
87	          name: true,
88	        },
89	      },
90	      author: {
91	        select: {
92	          username: true,
93	          bio: true,
94	          image: true,
95	          followedBy: true,
96	        },
97	      },
98	      favoritedBy: true,
99	      _count: {
100	        select: {
101	          favoritedBy: true,
102	        },
103	      },
104	    },
105	  });
106	
107	  return {
108	    articles: articles.map((article: any) => articleMapper(article, id)),
109	    articlesCount,
110	  };
111	};
112	
113	export const getFeed = async (offset: number, limit: number, id: number) => {
114	  const articlesCount = await prisma.article.count({
115	    where: {
116	      author: {
117	        followedBy: { some: { id: id } },
118	      },
119	    },
120	  });
121	
122	  const articles = await prisma.article.findMany({
123	    where: {
124	      author: {
125	        followedBy: { some: { id: id } },
126	      },
127	    },
128	    orderBy: {
129	      createdAt: 'desc',
130	    },
131	    skip: offset || 0,
132	    take: limit || 10,
133	    include: {
134	      tagList: {
135	        select: {
136	          name: true,
137	        },
138	      },
139	      author: {
140	        select: {
141	          username: true,
142	          bio: true,
143	          image: true,
144	          followedBy: true,
145	        },
146	      },
147	      favoritedBy: true,
148	      _count: {
149	        select: {
150	          favoritedBy: true,
151	        },
152	      },
153	    },
154	  });
155	
156	  return {
157	    articles: articles.map((article: any) => articleMapper(article, id)),
158	    articlesCount,
159	  };
160	};
