162	export const createArticle = async (article: any, id: number) => {
163	  const { title, description, body, tagList } = article;
164	  const tags = Array.isArray(tagList) ? tagList : [];
165	
166	  if (!title) {
167	    throw new HttpException(422, { errors: { title: ["can't be blank"] } });
168	  }
169	
170	  if (!description) {
171	    throw new HttpException(422, { errors: { description: ["can't be blank"] } });
172	  }
173	
174	  if (!body) {
175	    throw new HttpException(422, { errors: { body: ["can't be blank"] } });
176	  }
177	
178	  const slug = `${slugify(title)}-${id}`;
179	
180	  const existingTitle = await prisma.article.findUnique({
181	    where: {
182	      slug,
183	    },
184	    select: {
185	      slug: true,
186	    },
187	  });
188	
189	  if (existingTitle) {
190	    throw new HttpException(422, { errors: { title: ['must be unique'] } });
191	  }
192	
193	  const {
194	    authorId,
195	    id: articleId,
196	    ...createdArticle
197	  } = await prisma.article.create({
198	    data: {
199	      title,
200	      description,
201	      body,
202	      slug,
203	      tagList: {
204	        connectOrCreate: tags.map((tag: string) => ({
205	          create: { name: tag },
206	          where: { name: tag },
207	        })),
208	      },
209	      author: {
210	        connect: {
211	          id: id,
212	        },
213	      },
214	    },
215	    include: {
216	      tagList: {
217	        select: {
218	          name: true,
219	        },
220	      },
221	      author: {
222	        select: {
223	          username: true,
224	          bio: true,
225	          image: true,
226	          followedBy: true,
227	        },
228	      },
229	      favoritedBy: true,
230	      _count: {
231	        select: {
232	          favoritedBy: true,
233	        },
234	      },
235	    },
236	  });
237	
238	  return articleMapper(createdArticle, id);
239	};
240	
241	export const getArticle = async (slug: string, id?: number) => {
242	  const article = await prisma.article.findUnique({
243	    where: {
244	      slug,
245	    },
246	    include: {
247	      tagList: {
248	        select: {
249	          name: true,
250	        },
251	      },
252	      author: {
253	        select: {
254	          username: true,
255	          bio: true,
256	          image: true,
257	          followedBy: true,
258	        },
259	      },
260	      favoritedBy: true,
261	      _count: {
262	        select: {
263	          favoritedBy: true,
264	        },
265	      },
266	    },
267	  });
268	
269	  if (!article) {
270	    throw new HttpException(404, { errors: { article: ['not found'] } });
271	  }
272	
273	  return articleMapper(article, id);
274	};
275	
276	const disconnectArticlesTags = async (slug: string) => {
277	  await prisma.article.update({
278	    where: {
279	      slug,
280	    },
281	    data: {
282	      tagList: {
283	        set: [],
284	      },
285	    },
286	  });
287	};
288	
289	export const updateArticle = async (article: any, slug: string, id: number) => {
290	  let newSlug = null;
291	
292	  const existingArticle = await await prisma.article.findFirst({
293	    where: {
294	      slug,
295	    },
296	    select: {
297	      author: {
298	        select: {
299	          id: true,
300	          username: true,
301	        },
302	      },
303	    },
304	  });
305	
306	  if (!existingArticle) {
307	    throw new HttpException(404, {});
308	  }
309	
310	  if (existingArticle.author.id !== id) {
311	    throw new HttpException(403, {
312	      message: 'You are not authorized to update this article',
313	    });
314	  }
315	
316	  if (article.title) {
317	    newSlug = `${slugify(article.title)}-${id}`;
318	
319	    if (newSlug !== slug) {
320	      const existingTitle = await prisma.article.findFirst({
321	        where: {
322	          slug: newSlug,
323	        },
324	        select: {
325	          slug: true,
326	        },
327	      });
328	
329	      if (existingTitle) {
330	        throw new HttpException(422, { errors: { title: ['must be unique'] } });
331	      }
332	    }
333	  }
334	
335	  const tagList =
336	    Array.isArray(article.tagList) && article.tagList?.length
337	      ? article.tagList.map((tag: string) => ({
338	          create: { name: tag },
339	          where: { name: tag },
340	        }))
341	      : [];
342	
343	  await disconnectArticlesTags(slug);
344	
345	  const updatedArticle = await prisma.article.update({
346	    where: {
347	      slug,
348	    },
349	    data: {
350	      ...(article.title ? { title: article.title } : {}),
351	      ...(article.body ? { body: article.body } : {}),
352	      ...(article.description ? { description: article.description } : {}),
353	      ...(newSlug ? { slug: newSlug } : {}),
354	      updatedAt: new Date(),
355	      tagList: {
356	        connectOrCreate: tagList,
357	      },
358	    },
359	    include: {
360	      tagList: {
361	        select: {
362	          name: true,
363	        },
364	      },
365	      author: {
366	        select: {
367	          username: true,
368	          bio: true,
369	          image: true,
370	          followedBy: true,
371	        },
372	      },
373	      favoritedBy: true,
374	      _count: {
375	        select: {
376	          favoritedBy: true,
377	        },
378	      },
379	    },
380	  });
381	
382	  return articleMapper(updatedArticle, id);
383	};
384	
385	export const deleteArticle = async (slug: string, id: number) => {
